def droid(robot_arm, gripper, cameras):
    """Real single-arm Franka (DROID) + Robotiq gripper + ZED cameras."""
    observations = {
        'robot_state': Observation(robot_arm.state, Serializers.robot_state),
        keys.GRIP: Observation(gripper.grip, None),
        **{name: Observation(cam.frame, Serializers.camera_images) for name, cam in cameras.items()},
    }
    commands = {
        'robot_command': Command(robot_arm.commands, roboarm_command.Reset(), Serializers.robot_command),
        'target_grip': Command(gripper.target_grip, 0.0, None),
    }
    return Embodiment(
        descriptor='',
        observations=observations,
        commands=commands,
        static_meta=dict(ROBOT_STATIC_META),
        meta_source=robot_arm.robot_meta,
        control_systems=(*cameras.values(), robot_arm, gripper),
        simulated=False,
    )

def _build_obs(self, clock: pimm.Clock) -> dict[str, Any] | None:
    """Read every observation channel and assemble the policy input dict.

    Raises ``NoValueException`` (caught by ``run``) if any channel has no value
    yet — so inference waits for a complete set of inputs. Returns ``None`` if a
    serializer reports a sample is not ready (e.g. ``robot_state`` while the arm is
    ``RESETTING``), so the harness skips inference rather than feeding a partial obs.
    """
    inputs: dict[str, Any] = {}
    for name, obs in self._embodiment.observations.items():
        value = self.observations[name].value
        if obs.serializer is not None:
            value = obs.serializer(value)
            if value is None:
                return None

@staticmethod
def _build_robot_meta(robot) -> dict:
    urdf_xml = robot.get_robot_model()
    meshes = {f.name: f.read_bytes() for f in _MESH_DIR.iterdir() if f.suffix == '.stl'}
    root = ET.fromstring(urdf_xml)
    # Rewrite mesh references to bare filenames matching the bundled STL meshes.
    # The libfranka URDF uses package:// URIs (e.g. package://franka_description/.../link0.dae)
    # and references .dae visual meshes we don't bundle. Strip unresolvable elements and
    # normalise remaining refs so the URDF is self-contained — matching the style of
    # fr3.urdf used by cfg.ds.internal for offline dataset transforms.
    for link in root.findall('link'):
        for tag in ('visual', 'collision'):
            for vc_el in list(link.findall(tag)):
                mesh_el = vc_el.find('.//mesh')
                if mesh_el is None:
                    continue
                basename = Path(mesh_el.get('filename', '')).name
                if basename in meshes:
                    mesh_el.set('filename', basename)
                else:
                    link.remove(vc_el)
        stl = link.get('name', '') + '.stl'
        if stl in meshes and link.find('visual') is None:
            ET.SubElement(ET.SubElement(link, 'visual'), 'geometry').append(ET.Element('mesh', filename=stl))
    # TODO: The arm driver should not own the gripper. Move the 2F-85 model to the gripper driver
    # (drivers/gripper) and compose the arm and gripper together at the embodiment level.
    gripper = attach_robotiq_2f85(root, meshes)
    return {
        'urdf': ET.tostring(root, encoding='unicode'),
        'joint_names': _revolute_joint_names(urdf_xml),
        'meshes': meshes,
        'control_frame': 'end_effector',
        'gripper': gripper,
    }

@staticmethod
def robot_state(state: State) -> dict[str, np.ndarray] | None:
    # ERROR, like RESETTING, is a not-ready state: drop the frame rather than record or infer on a
    # mid-error pose.
    if state.status in (RobotStatus.RESETTING, RobotStatus.ERROR):
        return None
    return {'.q': state.q, '.dq': state.dq, '.ee_pose': Serializers.transform_3d(state.ee_pose)}

ds_agent = None
if dataset_writer is not None:
    ds_agent = DsWriterAgent(dataset_writer, time_mode=time_mode, virtual_time=embodiment.simulated)
    for name, obs in embodiment.observations.items():
        if isinstance(obs.serializer, StatefulSerializer):
            raise TypeError(f"observation '{name}': stateful serializer can't be shared by policy and record paths")
        ds_agent.add_signal(name, obs.serializer)
        world.connect(obs.source, ds_agent.inputs[name])
    for name, cmd in embodiment.commands.items():
        # Command channels carry whole trajectories; flatten with last-writer-wins so the
        # recording is a dense per-command stream. See TrajectoryOverrideSerializer.
        ds_agent.add_signal(name, TrajectoryOverrideSerializer(cmd.serializer))
        world.connect(harness.commands[name], ds_agent.inputs[name])
    for name, priv in privileged.items():
        ds_agent.add_signal(name, priv.serializer)
        world.connect(priv.source, ds_agent.inputs[name])
